int background_w_gedf(
                     struct background * pba,
                     double a,
                     double * w_edf,
                     double * dw_over_da_edf,
                     double * integral_edf
                     ){
  double wi, wf, A, B;
  double y, f, exp_y;
  double logacB, logaB;
  double M, log_1_plus_acB, log_aB_plus_acB;
  double log_t, log_t_today, t, exp_minus_t, transition_fraction;
  double t_exp_minus_t;

  wi = pba->wi_edf;
  wf = pba->wf_edf;
  A = - wi + wf;
  B = pba->s_a_gedf * (1. + wf);

  if (pba->use_exp_gedf == _TRUE_) {
    /*
     * w(a) = wf + (wi-wf) exp[-ln(2) (a/ac)^q].
     * integral_edf is 3 int_a^1 [1+w(a')] dln(a').
     */
    log_t = log(log(2.)) + pba->q_gedf * (log(a) - log(pba->ac_gedf));
    log_t_today = log(log(2.)) - pba->q_gedf * log(pba->ac_gedf);

    if (log_t > log(-log(DBL_MIN))) {
      exp_minus_t = 0.;
      transition_fraction = 1.;
      /* Evaluate the asymptotic limit directly: t*exp(-t) -> 0.
       * Using DBL_MAX*0 below would produce NaN. */
      t_exp_minus_t = 0.;
    }
    else {
      t = exp(log_t);
      exp_minus_t = exp(-t);
      transition_fraction = -expm1(-t);
      t_exp_minus_t = t * exp_minus_t;
    }

    *w_edf = wi + (wf - wi) * transition_fraction;
    *dw_over_da_edf = (wf - wi) * pba->q_gedf
      * t_exp_minus_t / a;
    *integral_edf = 3. * (1. + wf) * log(1./a)
      + 3. * (wi - wf) / pba->q_gedf
      * (background_expint_E1_from_log_argument(log_t)
         - background_expint_E1_from_log_argument(log_t_today));

    class_test(!isfinite(*w_edf)
               || !isfinite(*dw_over_da_edf)
               || !isfinite(*integral_edf),
               pba->error_message,
               "Non-finite exponential GEDF background value at a=%g "
               "(w=%g, dw/da=%g, integral=%g, log(t)=%g).",
               a,
               *w_edf,
               *dw_over_da_edf,
               *integral_edf,
               log_t);

    return _SUCCESS_;
  }

  /* w(a) = (-wi + wf)/(1 + (ac/a)^(s_a(1+wf))) + wi */
  if (fabs(B) < 1e-14) {
    *w_edf = 0.5 * A + wi;
    *dw_over_da_edf = 0.;
    *integral_edf = 3. * (1. + *w_edf) * log(1./a);
    return _SUCCESS_;
  }

  y = B * (log(pba->ac_gedf) - log(a));
  if (y >= 0.) {
    exp_y = exp(-y);
    f = exp_y/(1. + exp_y);
"}

